{-# LANGUAGE OverloadedStrings #-}

-- | Exact compiled programs from the Apache-2.0 pinned native examples. The
-- serialized encrypted wallet material in those files is deliberately excluded.
module Workflows.NativeScripts (alwaysSucceedsV2, alwaysSucceedsV3, selfIndex, orderPairing, withdrawZero, v4Validator, v4Guard) where

-- IMPORTS --------------------------------------------------------------------

import qualified Cometa.Encoding.Cbor as Cbor
import Cometa.Error (Error)
import qualified Cometa.Script.Plutus as Plutus
import Data.Text (Text)

-- DEFINITIONS ----------------------------------------------------------------

program :: Plutus.Version -> Text -> IO (Either Error Plutus.PlutusScript)
program version text = do
  encoded <- Cbor.fromHex text
  pure (encoded >>= Plutus.fromBytes version . Cbor.toBytes)

-- Source: cardano-c eadb95cd3ca7f711c203d7f2f4ee21c150d4d7f1,
-- examples/src/reward_account_script_example.c, ALWAYS_SUCCEEDS_SCRIPT_V2.
alwaysSucceedsV2 :: IO (Either Error Plutus.PlutusScript)
alwaysSucceedsV2 = program Plutus.V2 ""

-- Source: cardano-c eadb95cd3ca7f711c203d7f2f4ee21c150d4d7f1,
-- examples/src/spend_from_validator_example.c, ALWAYS_SUCCEEDS_SCRIPT_V3.
alwaysSucceedsV3 :: IO (Either Error Plutus.PlutusScript)
alwaysSucceedsV3 = program Plutus.V3 ""

